module appleman_toastman(\n    input clk,\n    input rst_n,\n    input start,\n    input [2:0] len,\n    input [7:0] arr_0,\n    input [7:0] arr_1,\n    input [7:0] arr_2,\n    input [7:0] arr_3,\n    output reg [15:0] result,\n    output reg done\n);\n\n    localparam [3:0]\n        IDLE    = 4'd0,\n        CAPTURE = 4'd1,\n        SORT    = 4'd2,\n        COMPUTE = 4'd3,\n        FINISH  = 4'd4;\n\n    reg [3:0] state, next_state;\n    reg [7:0] sorted_arr [0:3];\n    reg [2:0] len_reg;\n    reg [2:0] i_sort, j_sort;\n    reg swap_occurred;\n    reg [7:0] swap_temp;\n    reg [15:0] temp_sum;\n    reg [2:0] compute_index;\n    reg [5:0] cycle_count;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            len_reg <= 3'd0;\n            sorted_arr[0] <= 8'd0;\n            sorted_arr[1] <= 8'd0;\n            sorted_arr[2] <= 8'd0;\n            sorted_arr[3] <= 8'd0;\n            i_sort <= 3'd0;\n            j_sort <= 3'd0;\n            swap_occurred <= 1'b0;\n            swap_temp <= 8'd0;\n            temp_sum <= 16'd0;\n            compute_index <= 3'd0;\n            cycle_count <= 6'd0;\n            result <= 16'd0;\n            next_state <= IDLE;\n        end else begin\n            state <= next_state;\n\n            if (state != IDLE)\n                cycle_count <= cycle_count + 6'd1;\n            else\n                cycle_count <= 6'd0;\n\n            case(state)\n                IDLE: begin\n                    done <= 1'b0;\n                    next_state <= start ? CAPTURE : IDLE;\n                end\n\n                CAPTURE: begin\n                    sorted_arr[0] <= arr_0;\n                    sorted_arr[1] <= arr_1;\n                    sorted_arr[2] <= arr_2;\n                    sorted_arr[3] <= arr_3;\n                    len_reg <= len;\n                    i_sort <= 3'd0;\n                    j_sort <= 3'd0;\n                    swap_occurred <= 1'b0;\n                    next_state <= SORT;\n                end\n\n                SORT: begin\n                    if (cycle_count >= 6'd50) begin\n                        temp_sum <= 16'd0;\n                        compute_index <= 3'd0;\n                        next_state <= COMPUTE;\n                    end else if (i_sort < (len_reg - 1)) begin\n                        if (j_sort < (len_reg - 1 - i_sort)) begin\n                            if (sorted_arr[j_sort] > sorted_arr[j_sort + 1]) begin\n                                swap_temp <= sorted_arr[j_sort];\n                                sorted_arr[j_sort] <= sorted_arr[j_sort + 1];\n                                sorted_arr[j_sort + 1] <= swap_temp;\n                                swap_occurred <= 1'b1;\n                            end\n                            j_sort <= j_sort + 3'd1;\n                            next_state <= SORT;\n                        end else begin\n                            if (swap_occurred) begin\n                                swap_occurred <= 1'b0;\n                                i_sort <= i_sort + 3'd1;\n                                j_sort <= 3'd0;\n                                next_state <= SORT;\n                            end else begin\n                                temp_sum <= 16'd0;\n                                compute_index <= 3'd0;\n                                next_state <= COMPUTE;\n                            end\n                        end\n                    end else begin\n                        temp_sum <= 16'd0;\n                        compute_index <= 3'd0;\n                        next_state <= COMPUTE;\n                    end\n                end\n\n                COMPUTE: begin\n                    if (compute_index < len_reg) begin\n                        temp_sum <= temp_sum + (sorted_arr[compute_index] * (compute_index + 3'd2));\n                        compute_index <= compute_index + 3'd1;\n                        next_state <= COMPUTE;\n                    end else begin\n                        result <= temp_sum - sorted_arr[len_reg - 1];\n                        next_state <= FINISH;\n                    end\n                end\n\n                FINISH: begin\n                    done <= 1'b1;\n                    next_state <= IDLE;\n                end\n\n                default: next_state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule